urn:mrr:method-ruling:01KY1SNYNABM3R1GTAGA3S5D9V	2	mrr/v1alpha1	MethodRuling	urn:mrr:practice:01KY1SNY86X0GDE2N9TVZKT4YF	2026-07-21 07:36:39.856301+00	urn:mrr:agent-role:01KY1SNY86X0GDE2N9TVZKT4YD	sha256:3c936efdd4d92955eaebcc49fe0b6d547b60a74db6978ce8cb4c37a9284b31ea	\N	null	{"id": "urn:mrr:method-ruling:01KY1SNYNABM3R1GTAGA3S5D9V", "kind": "MethodRuling", "status": "issued", "revision": 2, "issued_by": "urn:mrr:agent-role:01KY1SNY86X0GDE2N9TVZKT4YD", "created_at": "2026-07-21T07:36:39.856301+00:00", "created_by": "urn:mrr:agent-role:01KY1SNY86X0GDE2N9TVZKT4YD", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY1SNY86X0GDE2N9TVZKT4YF", "protocol_id": "urn:mrr:method-protocol:01KY1SNYA6CZAYGFVVP0PA2QC0", "content_hash": "sha256:3c936efdd4d92955eaebcc49fe0b6d547b60a74db6978ce8cb4c37a9284b31ea", "ruling_basis": "deterministic_rule", "ruled_ceiling": "associational_unadjusted", "scope_of_validity": {"time": "atlas snapshots pinned 2026-07-21 at the recorded content hashes", "conditions": ["work must be catalogued in the pinned works-atlas snapshot, not merely mentioned in secondary commentary", "theory-side corroboration is drawn only from the pinned theory-atlas snapshot's own model-collapse keyword match over tags/summary/work"], "population": "works in the pinned works-atlas snapshot (corpora/model-collapse/works-atlas.snapshot.json, sha256:9d14e877efb245cc04b8451734b26285a274dda0418f5131db257d2e4312d373, 214 verified data/AI artworks) whose own `clusters` array contains 7 (\\"AI self-consumption\\" per src/data/field/clusters.json) — corroborated against the pinned theory-atlas snapshot (corpora/model-collapse/theory-atlas.snapshot.json, sha256:f712ea4e9c6b9137fa180ad91e73a86d8d09862792f33174c77acd76a891e610, 87 provenance-verified sources) for the model-collapse mechanism's own existence"}, "applies_to_analysis": "model-collapse-mechanism-theory-confirmation", "deterministic_rule_reference": "k1-t03.eligibility_and_ceiling_rules.v1", "non_applicability_conditions": ["Findings characterize only the pinned atlas snapshots (theory atlas sha256:f712ea4e9c6b9137fa180ad91e73a86d8d09862792f33174c77acd76a891e610, 87 entries; works atlas sha256:9d14e877efb245cc04b8451734b26285a274dda0418f5131db257d2e4312d373, 214 entries), not the full population of AI-self-consumption artworks or model-collapse literature beyond what each atlas has catalogued.", "Findings do not extend to works or papers outside the deterministic candidate sets fixed before classification (works-atlas cluster-7 membership; theory-atlas model-collapse keyword match).", "Findings about individual works are bounded by what each atlas's own decisive_move/summary field discloses about that work's production process; an atlas record silent on training provenance cannot license a stronger claim than the record supports."]}
urn:mrr:evidence-matrix:01KY1SNYJMTHE1XNDATAY0R2HY	3	mrr/v1alpha1	EvidenceMatrix	urn:mrr:practice:01KY1SNY86X0GDE2N9TVZKT4YF	2026-07-21 07:36:39.881657+00	urn:mrr:agent-role:01KY1SNY86X0GDE2N9TVZKT4YD	sha256:a68a10c710371f4523bdbccec10b847e149d4a6d8862adcc129b776abd1a6c6e	\N	null	{"id": "urn:mrr:evidence-matrix:01KY1SNYJMTHE1XNDATAY0R2HY", "kind": "EvidenceMatrix", "rows": [{"row_id": "theory-shumailov-curse-of-recursion", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\",\\"fehler\\"]; summary: \\"Shows generative models degrade when trained on their own output — model collapse\\" — a primary theoretical source directly describing the mechanism; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY1SNYDHG2V573AEMWM2W5H3", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYDP8ARZXPJZ41KG5ZKM", "verification_status": "verified", "claim_relevant_finding": "Shows generative models degrade when trained on their own output — model collapse: the tails of the distribution vanish first. Peer-reviewed as 'AI models collapse when trained on recursively generated data', Nature 631 (2024); open access on arXiv."}, {"row_id": "theory-alemohammad-self-consuming-mad", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\",\\"fehler\\"]; summary: \\"autophagous training loops across image models ... progressively decays — termed Model Autophagy Disorder (MAD)\\" — a primary theoretical source, independent author team and venue from shumailov/gerstgrasser; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY1SNYDWG3ADS9NDR1RXRMGR", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYE1PYBWY67T5GS7NEJA", "verification_status": "verified", "claim_relevant_finding": "Analyzes autophagous training loops across image models: without enough fresh real data in each generation, quality or diversity progressively decays — termed Model Autophagy Disorder (MAD). Open access on arXiv; no further formal venue recorded in the atlas."}, {"row_id": "theory-gerstgrasser-model-collapse-inevitable", "extraction": {"classification_basis": "tags: [\\"maschine/ki\\",\\"computation\\"]; summary: \\"accumulating synthetic data alongside real data ... bounds the error across LLMs, diffusion models and VAEs\\" — a primary theoretical source corroborating the same mechanism from a third, independent author team and venue; classified supports."}, "source_record_id": "urn:mrr:source-record:01KY1SNYE5XB3WTPMWA4YZ5F86", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYEAWVPY7TPCNXRSX3J2", "verification_status": "verified", "claim_relevant_finding": "Shows collapse is not fate: accumulating synthetic data alongside real data — instead of replacing it — bounds the error across LLMs, diffusion models and VAEs. Also published at COLM 2024; open access on arXiv."}, {"row_id": "works-heaney-ent-non-earthly-delights", "extraction": {"classification_basis": "decisive_move describes a physical sculpture about quantum computing and surveillance capitalism, with no documented model-generation-to-model-generation training loop at all (ConceptCharter instantiate-vs-reference-v1 Step 2: thematizes AI surveillance rather than instantiating the mechanism); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYEFWCQYJWDME6QR06DQ", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYEM0PYKTJSW5YDZ42RP", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"A physical 'quantum cyborg' sculpture (mild steel, fibreglass, acrylic, plus AR layers) staging Bosch's Garden of Earthly Delights as a warning about quantum computing's coming acceleration of AI-driven surveillance capitalism; Heaney explicitly frames dissolving/'sliming' as a strategy of resistance against detection systems.\\""}, {"row_id": "works-wilding-ai-lab", "extraction": {"classification_basis": "decisive_move describes examining the training/generation process as artistic material, but discloses no demonstrable model-output-fed-back-as-training-input loop across >=2 generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYESHXC15E34VK4C2P3D", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYEYNF9BNWWVTMMP83RC", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An open, participatory lab inside a spatial-audio dome where invited artists collectively 'reopen the black box' of generative AI models in public, treating the training/generation process itself — not just its output — as the artistic material.\\""}, {"row_id": "works-chronus-ai-delivered-abject", "extraction": {"classification_basis": "decisive_move describes GAN-trained works probing epistemological breakdown, but discloses no recursive model-generation-to-model-generation training loop (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYF2BEADVNNAEWJEB4H5", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYF7QWAZNQ7K8Z2V8K2J", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Group exhibition of GAN-trained films, a real-time AI dialogue-generating website, and an 'artificial counter-intelligence machine,' collectively probing where AI's competence gives way to abjection and epistemological breakdown.\\""}, {"row_id": "works-baudelaire-en-attendant-le-recit", "extraction": {"classification_basis": "decisive_move describes live inference-time conversation between already-trained models, not model-generated output fed back as training data for a subsequent generation (Step 1 not cleared — a looping CONVERSATION, not a looping TRAINING process); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYFB69S1WW9MTNJ7NW30", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYFGNTK0XCJPEWHP9ZA3", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Three chatbot models (ChatGPT, Claude, Mistral) are each given a character and voice through a speaker on one of three benches arranged in a triangle, and left to converse live about AI anxiety and 'the end of grand narratives' — an unscripted, looping machine dialogue restaged as improvised theatre, restarting every seven minutes.\\""}, {"row_id": "works-kurant-errorism", "extraction": {"classification_basis": "decisive_move states the model is trained on \\"her own writings\\" (the artist's own prior, human-authored text), not a PRIOR GENERATION OF THE MODEL'S OWN output — this is exactly ConceptCharter instantiate-vs-reference-v1 Step 2's named case (\\"trains on human-authored material (even the artist's own prior writing) without a demonstrable model-generation-to-model-generation loop\\"); a genuinely ambiguous, flagged case (task-packets/K1-T04.yaml derived_decisions (e)), resolved here per the charter's own Step 2 text; classified references-only/contradicts, not qualifies, because the atlas's own decisive_move discloses the input as the artist's own writing, not the model's own prior-generation output."}, "source_record_id": "urn:mrr:source-record:01KY1SNYFN8CMCH3Y3YTQRP9RA", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYFS2EH5BT0NGZKA42E6", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Kurant feeds her own writings into GPT-2 and GPT-3 and renders the output as a holographic animation, literally closing the loop of a model trained on and regurgitating one author's own words — a small, self-contained demonstration of the recursive self-consumption/collapse dynamic at stake in cluster 7.\\""}, {"row_id": "works-raikhy-hallucinations-of-an-artifact", "extraction": {"classification_basis": "decisive_move describes live performance collaboration with a generative-AI avatar, with no documented recursive training loop across generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYFYE24QDX64P8T9XBZE", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYG3C33NCV5B78YYHFB6", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Dancers improvise alongside a generative-AI avatar to invent speculative alternate lives for a prehistoric Indus Valley bronze statue, using an AI model as collaborator in reanimating an artifact whose original meaning is otherwise irrecoverable.\\""}, {"row_id": "works-ubermorgen-next-biennial-machine", "extraction": {"classification_basis": "decisive_move states the model is trained once on real Biennial/Whitney archives and then generates continuously, with no described retraining on its own prior-generation output (Step 1 not cleared); classified references-only/contradicts. Atlas verify_status is 'toVerify', not 'verified' — mapped to CorpusEntry verification_status 'pending' (task-packets/K1-T04.yaml derived_decisions (c)). The row is never dropped from the frozen matrix (MRR-MTH-015). Its own 'contradicts' evidence_relation still groups it into the contradicting-entry set the claim's own assertion text is built from (mrr.services.node_runtime.synthesis_executor._build_assertion has no verification-status filter), but mrr.domain.source_independence.distinct_independent_source_family_count only counts 'verified' rows, so this row contributes zero to the numeric contradicting-family tally that actually determines eligibility (13, not 14, distinct families) — the same 'verified'-only rule also excludes it from the separate min_included_sources kill-condition count. The eligibility outcome is unaffected either way."}, "source_record_id": "urn:mrr:source-record:01KY1SNYG77SYPX4W8AGNSQA9T", "verification_status": "pending", "claim_relevant_finding": "decisive_move: \\"An AI trained on real Biennial and Whitney archives endlessly hallucinates fake artist biographies and press releases, exposing algorithmic curation's absurdity by actually letting a machine attempt it, live, forever.\\""}, {"row_id": "works-mavropoulou-sleight-of-the-machine", "extraction": {"classification_basis": "decisive_move describes a single AI video model's inference-time failures kept on screen, with no documented recursive retraining loop across generations (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYGCBDB4ZZG17AB7WXD7", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYGG26EMGC40Y537ASR2", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An AI video model is cast as a stage magician performing sleight-of-hand; rather than concealing the model's characteristic failures (hands multiplying, morphing, defying physics), the film keeps every glitch on screen as the actual 'trick' — generative failure turned into the evidentiary content.\\""}, {"row_id": "works-hammond-v3-model-collapse", "extraction": {"classification_basis": "decisive_move states plainly: \\"each exhibition's own photographs and collages are fed back as training data for the next\\" — model-GENERATED output (the prior exhibition's own photographs/collages) fed back as training input for a SUBSEQUENT generation of a continuous pipeline, across at least three named generations (V1-V4) — clears ConceptCharter instantiate-vs-reference-v1 Step 1 cleanly, and the atlas's own text names the result \\"literalizes AI model collapse\\"; classified instantiates/supports."}, "source_record_id": "urn:mrr:source-record:01KY1SNYGNEMN6VTBPCFQMBW4B", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYGTAQGH16MFWCK305JG", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Third chapter of a four-part project in which each exhibition's own photographs and collages are fed back as training data for the next - literalizes AI model collapse as a visible, physically-installed material process, and draws an explicit parallel between data mining and geological mining extraction.\\""}, {"row_id": "works-hailesilassie-6500-alphabets", "extraction": {"classification_basis": "decisive_move describes a physical installation of digitized pictographs proposing an alternative epistemics, with no generative-model recursive training loop described at all (Step 1 not cleared, not even a generative-AI production pipeline); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYGY10JDZCKKCP8XQ5T2", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYH3TXCAZST8FK84DEBH", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Large-scale dome installation built from 6,500 digitized African pictographs, syllabaries and ideographs (extending the artist's 2019–2023 'Ancestral Algorithm' project) that reframes 'algorithm' as 'algo + rhythm', proposing indigenous knowledge systems as an alternative computational epistemics rather than an ornament to it.\\""}, {"row_id": "works-salu-ginzburg-cybernetics-or-ghosts", "extraction": {"classification_basis": "decisive_move describes human-authored fiction responding to a 1967 essay, with no generative-model training loop of any kind described (Step 1 not cleared, not even a generative-AI production pipeline); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYH8M4GXEMBQA5J9QK95", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYHCRWQW5ABHZPV42AKZ", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Fifteen writers respond in fiction to Italo Calvino's 1967 essay on cybernetics and myth, paired with a companion album, using the generative-AI moment as a mirror held up to older mythic and oral world-building traditions.\\""}, {"row_id": "works-dominguez-matrix-vegetal", "extraction": {"classification_basis": "decisive_move describes a video installation about plant-healing and quantum-inspired technology, with no generative-model recursive training loop described (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYHH3B03FF0Z3C1P8EFC", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYHNFRBM6X7AT0S6WGVA", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"A video installation braids Peruvian plant-healing practices together with 'quantum-inspired' technology, treating indeterminacy and non-Western epistemics of plant communication as equally valid registers of knowledge alongside computation.\\""}, {"row_id": "works-rahal-mythmachine", "extraction": {"classification_basis": "decisive_move describes a live, real-time audio-reactive feedback loop (behavior responding to ambient sound), not model-generated output recycled as training data across discrete generations — a genuinely different mechanism from recursive training (Step 1 not cleared); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYHT8KKXQ1HVRKKC4WFG", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYHYMQGHPTZ8MKQY1T2T", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"An AI-driven virtual biome of post-human creatures listens to and choreographs itself from ambient audio feedback captured live in the gallery, proposing folklore-derived 'other' intelligences as an alternative to extractive machine learning.\\""}, {"row_id": "works-giraud-feral-epoch-1", "extraction": {"classification_basis": "decisive_move states successive human ARTISTS feed one continuous AI across generations of human curators, not the model's own prior-generation output fed back as training data — this is ConceptCharter Step 2's named case (trains on human-authored material across generations of human feeders, without a demonstrable model-generation-to-model-generation loop); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYJ277CYWXYJ6VRT4042", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYJ73E11ZYJZ54CBSE02", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"First chapter of a planned 1,000-year, 32-generation project in which successive artists 'feed' one AI so it can eventually make a film witnessing humanity's end — a deliberately glacial experiment in what a machine 'learns' across centuries rather than scraped-in-seconds data.\\""}, {"row_id": "works-cheng-thousand-lives-bob", "extraction": {"classification_basis": "decisive_move describes live, continuous belief-updating inference (a running simulation), not discrete-generation retraining on the model's own prior output (Step 1 not cleared — inference-time belief updating is a different mechanism from recursive training); classified references-only/contradicts."}, "source_record_id": "urn:mrr:source-record:01KY1SNYJC3TNBZSZ1AG9T4G3D", "evidence_anchor_id": "urn:mrr:evidence-anchor:01KY1SNYJG6W7DVSDK3ZCX3EC4", "verification_status": "verified", "claim_relevant_finding": "decisive_move: \\"Extends Cheng's neurosymbolic autonomous-agent architecture (originally built for BOB, 2018-19) into a live, indefinitely-running simulation of a pet turtle's daily belief-updating - an actually-executing inferential AI system exhibited as artwork rather than a fixed narrative or render.\\""}], "status": "frozen", "revision": 3, "created_at": "2026-07-21T07:36:39.881657+00:00", "created_by": "urn:mrr:agent-role:01KY1SNY86X0GDE2N9TVZKT4YD", "api_version": "mrr/v1alpha1", "practice_id": "urn:mrr:practice:01KY1SNY86X0GDE2N9TVZKT4YF", "protocol_id": "urn:mrr:method-protocol:01KY1SNYA6CZAYGFVVP0PA2QC0", "question_id": "urn:mrr:question-model:01KY1SNY96A40KR82RSP0EJ34Z", "content_hash": "sha256:a68a10c710371f4523bdbccec10b847e149d4a6d8862adcc129b776abd1a6c6e"}
